import { logger } from "../logger.ts";

export interface RequestQueueOptions {
    maxConcurrent?: number;
    maxRetries?: number;
    retryDelay?: number;
}

export interface QueuedRequest<T> {
    key: string;
    request: () => Promise<T>;
    resolve: (value: T) => void;
    reject: (error: Error) => void;
    retries: number;
    timestamp: number;
}

export class RequestQueue {
    private queue: Map<string, QueuedRequest<unknown>> = new Map();
    private activeRequests: Set<string> = new Set();
    private maxConcurrent: number;
    private maxRetries: number;
    private retryDelay: number;

    public constructor(options: RequestQueueOptions = {}) {
        this.maxConcurrent = options.maxConcurrent ?? 5;
        this.maxRetries = options.maxRetries ?? 3;
        this.retryDelay = options.retryDelay ?? 1000;
    }

    public async enqueue<T>(key: string, request: () => Promise<T>): Promise<T> {
        const existing = this.queue.get(key);
        if (existing) {
            const typedExisting = existing as QueuedRequest<T>;
            return new Promise((resolve, reject) => {
                typedExisting.resolve = resolve;
                typedExisting.reject = reject;
            });
        }

        const queuedRequest: QueuedRequest<T> = {
            key,
            request,
            resolve: () => {},
            reject: () => {},
            retries: 0,
            timestamp: Date.now(),
        };

        this.queue.set(key, queuedRequest as QueuedRequest<unknown>);
        this.processQueue();

        return new Promise((resolve, reject) => {
            queuedRequest.resolve = resolve;
            queuedRequest.reject = reject;
        });
    }

    public async enqueueBatch<T>(requests: Array<{ key: string; request: () => Promise<T> }>): Promise<T[]> {
        return Promise.all(requests.map((r) => this.enqueue(r.key, r.request)));
    }

    public clear(key?: string): void {
        if (key) {
            const queued = this.queue.get(key);
            if (queued) {
                queued.reject(new Error("Request cancelled"));
                this.queue.delete(key);
            }
        } else {
            this.queue.forEach((queued: QueuedRequest<unknown>) => {
                queued.reject(new Error("Request cancelled"));
            });
            this.queue.clear();
        }
    }

    public getQueueSize(): number {
        return this.queue.size;
    }

    public getActiveRequestsCount(): number {
        return this.activeRequests.size;
    }

    private async processQueue(): Promise<void> {
        if (this.activeRequests.size >= this.maxConcurrent) {
            return;
        }

        const availableSlots = this.maxConcurrent - this.activeRequests.size;
        const entries = Array.from(this.queue.entries()).slice(0, availableSlots);

        for (const [key, queued] of entries) {
            if (this.activeRequests.has(key)) {
                continue;
            }

            this.activeRequests.add(key);
            this.executeRequest(queued);
        }
    }

    private async executeRequest<T>(queued: QueuedRequest<T>): Promise<void> {
        const { key, request, resolve, reject, retries } = queued;

        try {
            const result = await request();
            this.queue.delete(key);
            this.activeRequests.delete(key);
            resolve(result as T);
            this.processQueue();
        } catch (error) {
            const errorObj = error as Error;

            if (retries < this.maxRetries && this.isRetryableError(errorObj)) {
                queued.retries++;
                const backoffTime = this.retryDelay * Math.pow(2, retries);
                logger.warn(`Request ${key} failed, retry ${queued.retries}/${this.maxRetries} in ${backoffTime}ms`);

                setTimeout(() => {
                    this.activeRequests.delete(key);
                    this.executeRequest(queued);
                }, backoffTime);
            } else {
                this.queue.delete(key);
                this.activeRequests.delete(key);
                reject(errorObj);
                this.processQueue();
            }
        }
    }

    private isRetryableError(error: Error): boolean {
        return error.name === "FetchError" || error.name === "TimeoutError" || error.name === "AbortError";
    }
}
